function deLesson(data) {
    var vocab = [];
    data.groups.forEach(function (group) {
        group[1].forEach(function (word) {
            vocab.push({ k: data.id + '-' + vocab.length, t: word[0], pr: word[1], ar: word[2], g: group[0] });
        });
    });
    return {
        id: data.id,
        level: 'A1',
        icon: data.icon,
        title: data.title,
        sub: data.sub,
        goals: data.goals,
        vocab: vocab,
        dialog: { names: data.names, lines: data.lines.map(function (line) { return { w: line[0], t: line[1], ar: line[2] }; }) },
        notes: data.notes,
        quiz: data.quiz.map(function (item) { return { q: item[0], a: item[1], c: item[2] }; })
    };
}

